export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    const bytes: number[] = [];
    let n = num;

    while (n > 0) {
      const byte = n & 0x7F;
      n >>= 7;
      bytes.unshift(byte);
    }

    // Set continuation bit for all bytes except the last one
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80;
    }

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0n;
  let bitsCollected = 0;

  for (const byte of bytes) {
    // Validate byte range
    if (byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    // Check for continuation bit
    if ((byte & 0x80) === 0) {
      // Last byte
      if (bitsCollected === 0) {
        // Single byte number
        result.push(byte);
      } else {
        // Multi-byte number finished
        const finalValue = Number(currentNumber);
        if (finalValue > 0xFFFFFFFF) {
          throw new Error("Decoded number exceeds 32-bit unsigned integer range");
        }
        result.push(finalValue);
      }
      bitsCollected = 0;
      currentNumber = 0n;
    } else {
      // Not the last byte
      bitsCollected++;
      // Shift current number left by 7 and add new byte
      currentNumber = (currentNumber << 7n) | BigInt(byte);
    }
  }

  // If we exit the loop and bitsCollected > 0, it means the last byte didn't have the continuation bit cleared
  if (bitsCollected > 0) {
    throw new Error("Incomplete sequence: last byte missing continuation bit");
  }

  return result;
}
